DROP VIEW  IF EXISTS vw_catalogo_agente;
DROP VIEW  IF EXISTS vw_cotizacion_detalle;
DROP TABLE IF EXISTS cotizacion_items;
DROP TABLE IF EXISTS cotizaciones;
DROP TABLE IF EXISTS clientes;
DROP TABLE IF EXISTS productos;
DROP TABLE IF EXISTS categorias;

-- ------------------------------------------------------------
-- CLIENTES
-- ------------------------------------------------------------
CREATE TABLE clientes (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nombre      VARCHAR(100) NOT NULL,
  apellido    VARCHAR(100) NOT NULL,
  telefono    VARCHAR(20)  NOT NULL,
  correo      VARCHAR(150) NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_clientes_telefono (telefono),
  KEY idx_clientes_correo (correo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- CATEGORÍAS
-- ------------------------------------------------------------
CREATE TABLE categorias (
  id      SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  nombre  VARCHAR(80) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_categorias_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- PRODUCTOS 
-- ------------------------------------------------------------
CREATE TABLE productos (
  id                 INT UNSIGNED NOT NULL AUTO_INCREMENT,
  codigo             VARCHAR(60)  NOT NULL,
  nombre             VARCHAR(255) NOT NULL,
  categoria_id       SMALLINT UNSIGNED NULL,
  existencia         DECIMAL(12,3) NULL,
  inv_minimo         INT NOT NULL DEFAULT 0,
  inv_maximo         INT NOT NULL DEFAULT 0,
  activo             TINYINT(1) NOT NULL DEFAULT 1,
  requiere_revision  TINYINT(1) NOT NULL DEFAULT 0,
  nota_revision      VARCHAR(255) NULL,
  created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_productos_codigo (codigo),
  KEY idx_productos_categoria (categoria_id),
  KEY idx_productos_activo (activo),
  FULLTEXT KEY ft_productos_busqueda (nombre, codigo),
  CONSTRAINT fk_productos_categoria FOREIGN KEY (categoria_id)
    REFERENCES categorias (id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- COTIZACIONES 
-- ------------------------------------------------------------
CREATE TABLE cotizaciones (
  id                    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  cliente_id            INT UNSIGNED NOT NULL,
  estado                ENUM('borrador','enviada','cotizada','cerrada','cancelada')
                        NOT NULL DEFAULT 'borrador',
  canal                 VARCHAR(30) NOT NULL DEFAULT 'whatsapp',
  notas                 TEXT NULL,
  enviada_whatsapp_at   DATETIME NULL,
  created_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_cotizaciones_cliente (cliente_id),
  KEY idx_cotizaciones_estado (estado),
  CONSTRAINT fk_cotizaciones_cliente FOREIGN KEY (cliente_id)
    REFERENCES clientes (id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE cotizacion_items (
  id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
  cotizacion_id   INT UNSIGNED NOT NULL,
  producto_id     INT UNSIGNED NULL,
  descripcion     VARCHAR(255) NOT NULL,
  cantidad        DECIMAL(12,3) NOT NULL DEFAULT 1,
  unidad          VARCHAR(20) NOT NULL DEFAULT 'pza',
  created_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_items_cotizacion (cotizacion_id),
  KEY idx_items_producto (producto_id),
  CONSTRAINT fk_items_cotizacion FOREIGN KEY (cotizacion_id)
    REFERENCES cotizaciones (id) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_items_producto FOREIGN KEY (producto_id)
    REFERENCES productos (id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT chk_items_cantidad CHECK (cantidad > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE VIEW vw_catalogo_agente AS
SELECT p.id,
       p.codigo,
       p.nombre,
       c.nombre AS categoria,
       CASE WHEN p.existencia > 0 THEN 'disponible' ELSE 'consultar' END AS disponibilidad
FROM productos p
LEFT JOIN categorias c ON c.id = p.categoria_id
WHERE p.activo = 1;

CREATE VIEW vw_cotizacion_detalle AS
SELECT co.id                                   AS cotizacion_id,
       CONCAT('COT-', LPAD(co.id, 6, '0'))     AS folio,
       co.estado,
       co.created_at,
       cl.nombre, cl.apellido, cl.telefono, cl.correo,
       ci.cantidad, ci.unidad,
       ci.descripcion,
       p.codigo                                AS codigo_producto,
       p.nombre                                AS nombre_producto
FROM cotizaciones co
JOIN clientes cl          ON cl.id = co.cliente_id
JOIN cotizacion_items ci  ON ci.cotizacion_id = co.id
LEFT JOIN productos p     ON p.id = ci.producto_id;


